<script lang="ts">
    import { onMount } from "svelte";
    import { TooltipFactory } from "@/classes/TooltipFactory";
    import { TooltipDirection } from "@/enums/TooltipDirection";
    import type { SidebarRatioSliderProps } from "@/interfaces/actor/button/SidebarRatioSliderProps";
    import type { TextLogEventProps } from "@/interfaces/actor/TextLogEventProps";
    import type { TooltipProps } from "@/interfaces/actor/TooltipProps";
    import { getAdvancedState } from "@/scripts/store/advanced";
    import { getLocalized } from "@/scripts/helpers";
    import { resetTextConsole, sendToTextConsole } from "@/scripts/store/text-log";
    import { getActorContext } from "@/scripts/context";
    import { getExtraEffectsEnabled } from "@/scripts/settings";

    const props = $props();
    const { 
        uuid,
        ratioGetter,
        ratioSetter,
        
        style,

        tooltipEnabled,
        tooltipClass,
        tooltipTheme,

        logText,
        logging,
    }: SidebarRatioSliderProps & TooltipProps & TextLogEventProps = $derived(props)
    const actorUuid = getActorContext()?.uuid;

    // svelte-ignore state_referenced_locally
    let ratio = $state(ratioGetter(uuid));
    let component: HTMLElement | null = $state(null);
    let sidebar: JQuery<HTMLElement> | null = null;

    const qualityMode = getExtraEffectsEnabled();
    const advancedOptions = $derived(getAdvancedState(uuid));
    const log = $derived(logText || getLocalized("LA.advanced.sidebarRatio.tooltip"));

    const tip = TooltipFactory.buildTooltip(getLocalized("LA.advanced.sidebarRatio.tooltip"));

    // Force the sidebar to update its flex value based on the changes we make to ratio
    onMount(() => 
    {
        if (component)
        {
            sidebar = jQuery(component).closest('.la-root').find('.la-sidebar');
        }
    });

    function handleOnInput(event: Event)
    {
        const target = event.target as HTMLInputElement;
        const value = parseFloat(target.value);
        ratio = value;
        if (sidebar)
            sidebar.css('flex', value.toString());
    }

    function handleOnRelease(event: Event)
    {
        const target = event.target as HTMLInputElement;
        const value = parseFloat(target.value);
        ratio = value;
        ratioSetter(uuid, value);
    }
    
</script>
<!-- Ratio Slider -->
<div class="la-range {style?.join(' ')}
        {advancedOptions ? '-displayblock' : '-displaynone'}"
    bind:this={component}
>
    <input type="range"
        class="la-prmy-primary
            {qualityMode ? '-glow-prmy-hover' : ''}"
        min={0.5}
        max={2}
        value={ratio}
        step={0.1}
        data-tooltip={tooltipEnabled ? tip : undefined }
        data-tooltip-class={`${tooltipClass || "clipped-bot la-tooltip"} ${tooltipTheme}`}
        data-tooltip-direction={TooltipDirection.UP}
        oninput={event => handleOnInput(event)}
        onpointerup={event => handleOnRelease(event)}
        onpointerenter={ logging ? event => sendToTextConsole(event, log, actorUuid!) : undefined }
        onpointerleave={ logging ? event => resetTextConsole(event, actorUuid!) : undefined }
        aria-label={getLocalized("LA.advanced.sidebarRatio.tooltip")}
    />
</div>