<script lang="ts">
    import { id as moduleID } from '@/module.json';
    import { getLocalized } from "@/scripts/helpers";
    import { getPilotSheetTooltipEnabled } from "@/scripts/pilot/settings";
    import { PilotStore } from "@/scripts/store/module-store";
    import { resetTextConsole, sendToTextConsole } from "@/scripts/store/text-log";
    import { getThemeKey } from '@/scripts/store/theme';
    import { getBrightness, getCSSDocumentTheme } from "@/scripts/theme";
    import { TooltipDirection } from "@/enums/TooltipDirection";
    import { TooltipFactory } from "@/classes/TooltipFactory";
    import MechStats from "@/svelte/pilot/MechStats.svelte";
    import HeaderMain, { MAIN_HEADER_STYLE } from "@/svelte/shared/header/HeaderMain.svelte";
    import EmptyBox from "@/svelte/shared/EmptyBox.svelte";
    import { getExtraEffectsEnabled } from "@/scripts/settings";
    import { setActorContext } from "@/scripts/context";

    const props = $props();
    const {
        actor,
        system,
    } = $derived(props);
    setActorContext(actor);
    const ownedMechs: any[] = game.actors?.filter((mech: any) => 
        mech.type === "mech" && 
        mech.system.pilot?.status === "resolved" && 
        mech.system.pilot.value.id === actor.id) ?? [];
    // svelte-ignore state_referenced_locally
    let selectedMechIndex = $state(PilotStore.get(actor.uuid).selectedMech);

    const qualityMode = getExtraEffectsEnabled();
    const tooltipEnabled = getPilotSheetTooltipEnabled();
    const themeOverride = $derived(getBrightness(getThemeKey(actor.uuid)) === 'light' ? 'la-text-primary' : 'la-text-text');
    const collID = $derived(`${actor.uuid}.mechStorage`);
    const theme = $derived(getCSSDocumentTheme(actor.uuid));

    const activateTip = TooltipFactory.buildTooltip(getLocalized("LA.pilot.mechStorage.activate.tooltip"));
    const deactivateTip = TooltipFactory.buildTooltip(getLocalized("LA.pilot.mechStorage.deactivate.tooltip"));

    function isInactive()
    {
        return !system.active_mech || system.active_mech.id !== ownedMechs[selectedMechIndex].uuid;
    }
    
    function getGlowColor()
    {
        return isInactive() ? "la-prmy-system" : "la-prmy-text";
    }

    function getSizeTip()
    {
        return TooltipFactory.buildTooltip(getLocalized("LA.size.tooltip"), `${getLocalized("LA.size.label")} ${ownedMechs[selectedMechIndex].system.size}`);
    }

    function getSpeedTip()
    {
        return TooltipFactory.buildTooltip(getLocalized("LA.speed.tooltip"), `${getLocalized("LA.speed.label")} ${ownedMechs[selectedMechIndex].system.speed}`);
    }

    function handleMechSelect(event: Event, index: number)
    {
        event.stopPropagation();

        selectedMechIndex = index;
        PilotStore.set(actor.uuid, {
            selectedMech: index
        });
    }

    function setActiveMech(event: Event)
    {
        event.stopPropagation();

        if (system.active_mech && system.active_mech.id === ownedMechs[selectedMechIndex].uuid)
        {
            actor.update({
                ["system.active_mech"]: null
            })
        }
        else
        {
            ownedMechs[selectedMechIndex].update({
                ["system.pilot"]: actor.uuid
            });
            actor.update({
                ["system.active_mech"]: ownedMechs[selectedMechIndex].uuid
            })
        }
    }
</script>

{#if ownedMechs.length}
<div class="la-flexcol -widthfull -margin1-b -padding1-tb la-reveal-hover
        {qualityMode ? 'la-bg-scroll-alt' : 'la-bg-alt'}"
>
    <div class="-positionrelative -widthfull la-reveal">
        <span class="la-selected-mech__active -positionabsolute la-outl-header -bold -textaligncenter -letterspacing1 -widthfull -height5 -lineheight5 la-bckg-darken-2
            {isInactive() ? 'la-text-error' : 'la-text-system'}"
        >
        {#if isInactive()}
            {getLocalized("LA.pilot.mechstorage.inactive.label")}
        {:else}
            {getLocalized("LA.pilot.mechstorage.active.label")}
        {/if}
        </span>
    </div>
    <button 
        class="-fontsize6 -letterspacing1 -upper
            {qualityMode ? '-glow-hover-primary' : ''}
            ref set click-open"
        data-uuid={ownedMechs[selectedMechIndex].uuid}
        onpointerenter={ event => sendToTextConsole(event, getLocalized("LA.pilot.mechStorage.open.tooltip"), actor.uuid) }
        onpointerleave={ event => resetTextConsole(event, actor.uuid) }
        draggable={true}
    >
        {ownedMechs[selectedMechIndex].name}
    </button>
    <span class="-fontsizemedium -letterspacing0 -upper">
        {ownedMechs[selectedMechIndex].system.loadout.frame?.value.system.manufacturer || 
        getLocalized("LA.placeholder")}
    </span>
    <img
        class="la-selected-mech__img"
        src={ ownedMechs[selectedMechIndex].img === "systems/lancer/assets/icons/mech.svg" ? `modules/${moduleID}/assets/nodata.png` : ownedMechs[selectedMechIndex].img }
        alt={getLocalized("LA.placeholder")}
    />
    <div class="la-flexcol -positionabsolute -right0">
        <div class=" -fontsize19">
        {#if ownedMechs[selectedMechIndex].system.size < 1}
            <i class="cci cci-size-half {themeOverride} la-outl-shadow"
                data-tooltip={tooltipEnabled ? getSizeTip() : undefined}
                data-tooltip-class="clipped-bot la-tooltip {theme}"
                data-tooltip-direction={TooltipDirection.LEFT}></i>
        {:else}
            <i class="cci cci-size-{ownedMechs[selectedMechIndex].system.size} {themeOverride} la-outl-shadow"
                data-tooltip={tooltipEnabled ? getSizeTip() : undefined}
                data-tooltip-class="clipped-bot la-tooltip {theme}"
                data-tooltip-direction={TooltipDirection.LEFT}></i>
        {/if}
        </div>
        <div class=" la-flexrow -fontsize9" 
            data-tooltip={tooltipEnabled ? getSpeedTip() : undefined}
            data-tooltip-class="clipped-bot la-tooltip {theme}"
            data-tooltip-direction={TooltipDirection.LEFT}>
            <i class="mdi mdi-arrow-right-bold-hexagon-outline {themeOverride} la-outl-shadow"></i>
            <span class="{themeOverride} la-outl-shadow -bold">{ownedMechs[selectedMechIndex].system.speed}</span>
        </div>
    </div>
    <div class="-positionrelative">
        <button type="button"
            class="la-flexrow -widthfull -fontsize13 -positionabsolute -bottom0 
                {isInactive() ? 'cci cci-activate la-text-system' : 'cci cci-deactivate la-text-weapon'}
                {qualityMode ? '-glow-prmy la-prmy-primary -glow-prmy-hover' + getGlowColor() : ''}"
            data-tooltip={tooltipEnabled 
                ? isInactive() ? activateTip : deactivateTip 
                : undefined}
            data-tooltip-class="clipped-bot la-tooltip {theme}"
            data-tooltip-direction={TooltipDirection.DOWN}
            onpointerenter={ event => sendToTextConsole(event, isInactive()
                    ? getLocalized("LA.pilot.mechStorage.activate.tooltip")
                    : getLocalized("LA.pilot.mechStorage.deactivate.tooltip"),
                actor.uuid) }
            onpointerleave={ event => resetTextConsole(event, actor.uuid) }
            aria-label={isInactive() ? activateTip : deactivateTip }
            onclick={setActiveMech}
        ></button>
    </div>
</div>
<!-- Selectable Mechs -->
<HeaderMain
    text={getLocalized("LA.tab.mechs.label")}
    headerStyle={[MAIN_HEADER_STYLE, "la-bckg-primary"]}
    textStyle={["la-text-header -fontsize4 -overflowhidden"]}
    borderStyle={["la-brdr-transparent la-bckg-card clipped-bot-alt"]}

    collapseID={collID}
    startCollapsed={true}
>
    <div class="la-flexcol -widthfull">
        <div role="none"
            class="la-available-mechs__list"
            onpointerenter={ event => sendToTextConsole(event, getLocalized("LA.pilot.mechStorage.select.tooltip"), actor.uuid) }
            onpointerleave={ event => resetTextConsole(event, actor.uuid) }
        >
            <div class=" la-flexrow -justifystart -padding0-b">
            {#each ownedMechs as mech, index}
                <button type="button"
                    class="la-flexcol -bordersround {selectedMechIndex === index ? 'la-brdr-accent' : 'la-brdr-transparent'}"
                    onclick={event => handleMechSelect(event, index)}
                    aria-label={getLocalized("LA.pilot.mechStorage.select.tooltip")}
                >
                    <img 
                        class="la-available-mechs__img"
                        src={mech.img}
                        alt={getLocalized("LA.placeholder")}
                    >
                    <span class="-fontsizesmall -fontface-stylized">
                        {mech.name}
                    </span>
                </button>
            {/each}
            </div>
        </div>
    </div>
</HeaderMain>
<!-- Mech Stats -->
<MechStats
    actor={actor}
    selectedMech={ownedMechs[selectedMechIndex]}
/>
{:else}
    <EmptyBox
        label={getLocalized("LA.pilot.mechStorage.empty.label")}
        subLabel={getLocalized("LA.pilot.mechStorage.empty.subLabel")}
    />
{/if}