{#if itemTypes.skill.length}
<MacroDropBox
    uuid={actor.uuid}
    getExes={checkExecutables()}
    setExes={setSidebarExecutables}
    hintDropArea={true}
    allowDrop={advancedOptions}
    buttonStyle={[FLOW_BUTTON_DEFAULT(), advancedOptions ? "-margin7-l"  : "-margin2-l"]}
    tooltipEnabled={tooltipEnabled}
    logging={true}
/>
{/if}