<script lang="ts">
    import { ChatCardType } from "@/enums/ChatCardType";
    import { AcceptType } from "@/enums/AcceptType";
    import { CounterBoxType } from "@/enums/CounterBoxType";
    import { FlowClass } from "@/enums/FlowClass";
    import { TooltipDirection } from "@/enums/TooltipDirection";
    import { getLocalized } from "@/scripts/helpers";
    import { getCSSDocumentTheme } from "@/scripts/theme";
    import { getPilotSheetTooltipEnabled } from "@/scripts/pilot/settings";
    import { CHAT_CARD_COLOR_MAP } from "@/scripts/constants";
    import { Logger } from "@/classes/Logger";
    import { TooltipFactory } from "@/classes/TooltipFactory";
    import { SendUnknownToChatBase } from "@/classes/flows/SendUnknownToChat";
    import type { ChatData } from "@/interfaces/flows/ChatData";

    import HeaderMain, { MAIN_HEADER_STYLE } from "@/svelte/shared/header/HeaderMain.svelte";
    import HeaderSecondary, { H2_HEADER_STYLE, H2_ICON_SIZE, H2_TEXT_SIZE } from "@/svelte/shared/header/HeaderSecondary.svelte";
    import { H2_BUTTON_ICON_STYLE } from "@/svelte/shared/button/Button.svelte";
    import CollapseAllButton from "@/svelte/shared/button/CollapseAllButton.svelte";    import GlyphButton from "@/svelte/shared/button/GlyphButton.svelte";
    import ActionBox from "@/svelte/shared/ActionBox.svelte";
    import BonusBox from "@/svelte/shared/BonusBox.svelte";
    import CounterBox from "@/svelte/shared/counter/CounterBox.svelte";
    import DeployableBox from "@/svelte/shared/DeployableBox.svelte";
    import EffectBox from "@/svelte/shared/EffectBox.svelte";
    import EmptyBox from "@/svelte/shared/EmptyBox.svelte";
    import TagArray from "@/svelte/shared/TagArray.svelte";

    const {
        actor,
        armors
    } = $props();
    let collapseAllButtonHover = $state(false);
    let editButtonHover = $state(false);
    let messageButtonHover = $state(false);
    const [armorBonuses, otherBonuses] = $derived.by(() => armors.map((armor: any) => {
        // Separate bonuses into armor-related and other-related categories
        return armor.system.bonuses.reduce(
            (bonusCategories: { armorBonuses: { [key: string]: any }; otherBonuses: { [key: string]: any } }, bonus: { lid: string; val: any }) => {
                const isArmorBonus = ["pilot_hp", "pilot_armor", "pilot_evasion", "pilot_edef", "pilot_speed"].includes(bonus.lid);
                const categoryKey = isArmorBonus ? "armorBonuses" : "otherBonuses";
                bonusCategories[categoryKey][bonus.lid] = bonus.val;
                return bonusCategories;
            },
            { armorBonuses: {}, otherBonuses: {} }
        );
    }).reduce(
        (
            [armorBns, otherBns]: [{ [key: string]: number }[], { [key: string]: number }[]],
            { armorBonuses, otherBonuses }: { armorBonuses: { [_key: string]: number }; otherBonuses: { [_key: string]: number } }
        ) => {
            // Accumulate armor-related and other-related bonuses
            if (Object.keys(armorBonuses).length > 0)
                armorBns.push(armorBonuses);
            if (Object.keys(otherBonuses).length > 0)
                otherBns.push(otherBonuses);
            return [armorBns, otherBns];
        },
        [[], []]
    ));

    const tooltipEnabled = getPilotSheetTooltipEnabled();
    const collID = $derived(`${actor.uuid}.armors`);
    const theme = $derived(getCSSDocumentTheme(actor.uuid));

    const healthTip = TooltipFactory.buildTooltip(getLocalized("LA.pilot.hardsuit.health.tooltip"));
    const evasionTip = TooltipFactory.buildTooltip(getLocalized("LA.pilot.hardsuit.evasion.tooltip"));
    const edefenseTip = TooltipFactory.buildTooltip(getLocalized("LA.pilot.hardsuit.edefense.tooltip"));
    const speedTip = TooltipFactory.buildTooltip(getLocalized("LA.pilot.hardsuit.speed.tooltip"));
    const armorTip = TooltipFactory.buildTooltip(getLocalized("LA.pilot.hardsuit.armor.tooltip"));

    function getArmorPath(index: number)
    {
        return `itemTypes.pilot_armor.${index}`;
    }
    
    function sendToChat(event: MouseEvent & { currentTarget: EventTarget & HTMLElement }, armor: any)
    {
        event.stopPropagation();
        if (actor?.uuid && armor)
        {
            const description = `
                ${armor.system.description}
                <hr>
                <div 
                    class="la-flexrow -justifyevenly clipped-alt -fontsize5 -padding0-tb -padding1-lr" 
                    style="
                        background-color: var(--weapon-color);
                        color: var(--light-text);
                        align-items: baseline;
                    "
                >
                    <div>${armor.system.bonuses[0].val}<i class="mdi mdi-heart-half-full" style="padding-left: 2px; padding-right: 2px;"></i></div>
                    <div class="la-flexrow">${armor.system.bonuses[1].val}<i class="cci cci-role-defender -fontsize6"></i></div>
                    <div class="la-flexrow">${armor.system.bonuses[2].val}<i class="cci cci-evasion -fontsize6"></i></div>
                    <div class="la-flexrow">${armor.system.bonuses[3].val}<i class="cci cci-edef -fontsize6"></i></div>
                    <div>${armor.system.bonuses[4].val}<i class="mdi mdi-arrow-right-bold-hexagon-outline" style="padding-left: 2px; padding-right: 2px;"></i></div>
                </div>
            `
            let chatData = {
                title: armor.name, 
                description: description,
                tags: armor.system.tags,
                color: CHAT_CARD_COLOR_MAP[ChatCardType.Armor],
            } as ChatData
            SendUnknownToChatBase.getInstance().startFlow(armor.uuid, chatData);        
        }
        else
            Logger.error("Tried to call LAS sendToChat without either an actor's UUID or associated object");
    }
</script>

{#snippet headerOptions()}
<CollapseAllButton
    collapseID={collID}
    tooltipEnabled={tooltipEnabled}
    tooltipTheme={theme}

    onPointerEnter={() => {collapseAllButtonHover = true;}}
    onPointerLeave={() => {collapseAllButtonHover = false;}}
/>
{/snippet}

<HeaderMain
    text={getLocalized("LA.armor.label")}
    headerStyle={[MAIN_HEADER_STYLE, "la-bckg-weapon"]}
    textStyle={["la-text-header -fontsize4 -overflowhidden"]}
    borderStyle={["la-brdr-weapon"]}
    extensionTextFunction={() => {
        if (collapseAllButtonHover)
            return `--${getLocalized("LA.collapseAll.extension")}`;
        return undefined;
    }}
    
    collapseID={collID}
    startCollapsed={true}
    
    headerContent={headerOptions}
>
{#if armors.length}
    <div class="la-flexcol -gap0 -widthfull">
    {#each armors as armor, index}
    {#snippet outerContent()}
    {#if Object.keys(armorBonuses[index]).length}
        <div class="la-flexcol -gap0 -widthfull -padding2-l -fontface-stylized">
            <div class="la-flexrow clipped-bot-alt la-bckg-header-anti -widthfull -justifyevenly">
                {#if armorBonuses[index].pilot_hp}
                <span class="la-flexrow -justifycenter -aligncenter -fontsize5 -padding0-lr -padding0-tb la-text-header -gap0"
                    data-tooltip={tooltipEnabled ? healthTip : undefined}
                    data-tooltip-class="clipped-bot la-tooltip {theme}"
                    data-tooltip-direction={TooltipDirection.DOWN}
                >
                    {armorBonuses[index].pilot_hp}
                    <i class="mdi mdi-heart-half-full -fontsize5"></i>
                </span>
                {/if}
                {#if armorBonuses[index].pilot_armor}
                <span class="la-flexrow -justifycenter -aligncenter -fontsize5 -padding0-lr la-text-header"
                    data-tooltip={tooltipEnabled ? armorTip : undefined}
                    data-tooltip-class="clipped-bot la-tooltip {theme}"
                    data-tooltip-direction={TooltipDirection.DOWN}
                >
                    {armorBonuses[index].pilot_armor}
                    <i class="cci cci-role-defender -fontsize6"></i>
                </span>
                {/if}
                {#if armorBonuses[index].pilot_evasion}
                <span class="la-flexrow -justifycenter -aligncenter -fontsize5 -padding0-lr la-text-header"
                    data-tooltip={tooltipEnabled ? evasionTip : undefined}
                    data-tooltip-class="clipped-bot la-tooltip {theme}"
                    data-tooltip-direction={TooltipDirection.DOWN}
                >
                    {armorBonuses[index].pilot_evasion}
                    <i class="cci cci-evasion -fontsize6"></i>
                </span>
                {/if}
                {#if armorBonuses[index].pilot_edef}
                <span class="la-flexrow -justifycenter -aligncenter -fontsize5 -padding0-lr la-text-header"
                    data-tooltip={tooltipEnabled ? edefenseTip : undefined}
                    data-tooltip-class="clipped-bot la-tooltip {theme}"
                    data-tooltip-direction={TooltipDirection.DOWN}
                >
                    {armorBonuses[index].pilot_edef}
                    <i class="cci cci-edef -fontsize6"></i>
                </span>
                {/if}
                {#if armorBonuses[index].pilot_speed}
                <span class="la-flexrow -justifycenter -aligncenter -fontsize5 -padding0-lr la-text-header"
                    data-tooltip={tooltipEnabled ? speedTip : undefined}
                    data-tooltip-class="clipped-bot la-tooltip {theme}"
                    data-tooltip-direction={TooltipDirection.DOWN}
                >
                    {armorBonuses[index].pilot_speed}
                    <i class="mdi mdi-arrow-right-bold-hexagon-outline -fontsize5"></i>
                </span>
                {/if}
            </div>
        {#if armor.system.counters.length}
        {#each armor.system.counters as counter, jndex}
            <CounterBox
                text={counter.name}
                type={CounterBoxType.Counter}
                usesValue={counter.value}
                usesMax={counter.max}
                path="{getArmorPath(index)}.system.counters.{jndex}"
        
                logging={true}
            />
        {/each}
        {/if}
        </div>
    {/if}
    {/snippet}
    {#snippet headerSecondaryLeftOptions()}
        <i class="{H2_ICON_SIZE} cci cci-pilot"></i>
    {/snippet}
    {#snippet headerSecondaryRightOptions()}
        <!-- Edit -->
        <GlyphButton
            style={[H2_BUTTON_ICON_STYLE(), "-padding0-lr"]}
            flowClass={FlowClass.ContextMenu}
            path={getArmorPath(index)}

            tooltipEnabled={tooltipEnabled}
            tooltipDirection={TooltipDirection.UP}
            tooltipTheme={theme}
            tooltip={getLocalized("LA.edit.tooltip")}
            logText={getLocalized("LA.edit.tooltip")}
            logging={true}

            onPointerEnter={() => {editButtonHover = true;} }
            onPointerLeave={() => {editButtonHover = false;} }
        >
            <i class="fas fa-ellipsis-v"></i>
        </GlyphButton>
        <!-- Send to Chat -->
        <GlyphButton
            style={[H2_BUTTON_ICON_STYLE(), "-padding0-lr"]}
            flowClass={FlowClass.None}
            index={index}
            uuid={armor.uuid}

            tooltipEnabled={tooltipEnabled}
            tooltipDirection={TooltipDirection.UP}
            tooltipTheme={theme}
            tooltip={getLocalized("LA.chat.tooltip")}
            logText={getLocalized("LA.chat.tooltip")}
            logging={true}

            onClick={event => sendToChat(event, armor)}
            onPointerEnter={() => {messageButtonHover = true;} }
            onPointerLeave={() => {messageButtonHover = false;} }
        >
            <i class="mdi mdi-message"></i>
        </GlyphButton>
    {/snippet}
        <HeaderSecondary
            text={armor.name}
            headerStyle={[H2_HEADER_STYLE, "la-bckg-pilot"]}
            textStyle={[H2_TEXT_SIZE, "-overflowhidden -fontface-stylized"]}
            borderStyle={["-bordersoff"]}
            extensionTextFunction={() => {
                if (messageButtonHover)
                    return `--${getLocalized("LA.chat.extension")}`;
                if (editButtonHover)
                    return `--${getLocalized("LA.edit.extension")}`;
                return undefined;
            }}

            itemID={armor.id}
            uuid={armor.uuid}
            path={getArmorPath(index)}
            acceptTypes={"pilot_armor"}
            
            collapseID={armor.uuid}
            startCollapsed={true}

            renderOutsideCollapse={outerContent}
            contentLeft={headerSecondaryLeftOptions}
            contentRight={headerSecondaryRightOptions}
        >
            <div class="la-generated -widthfull -gap1 la-flexcol">
            {#if otherBonuses.length}
                <BonusBox
                    bonuses={otherBonuses}
                    bonusPath={`${getArmorPath(index)}.system.bonuses`}
                />
            {/if}
                <DeployableBox
                    source={actor}
                    lidSource={armor.system}
                    uuid={actor.uuid}
                    sheetUUID={actor.uuid}

                    tooltipEnabled={tooltipEnabled}
                    tooltipTheme={theme}
                    logging={true}
                />
                <ActionBox
                    actions={armor.system.actions}
                    actor={actor}
                    uuid={armor.uuid}
                    path={`system.actions`}

                    collapseID={`${armor.uuid}.actions`}
                    startCollapsed={true}

                    tooltipEnabled={tooltipEnabled}
                    tooltipTheme={theme}
                    logging={true}
                />
                <EffectBox
                    name={getLocalized("LA.description.label")}
                    effect={armor.system.description}

                    tooltipEnabled={tooltipEnabled}
                    logging={true}
                />
            {#if armor.system.effect}
                <EffectBox
                    name={getLocalized("LA.mech.system.effect.label")}
                    effect={armor.system.effect}

                    tooltipEnabled={tooltipEnabled}
                    logging={true}
                />
            {/if}
                <TagArray
                    tags={armor.system.tags}
                    justify={"start"}

                    tooltipEnabled={tooltipEnabled}
                    tooltipTheme={theme}
                />
            </div>
        </HeaderSecondary>
    {/each}
    </div>
{:else}
    <EmptyBox
        label={getLocalized("LA.pilot.hardsuit.empty.label")}
        subLabel={getLocalized("LA.pilot.hardsuit.empty.subLabel")}
        type={AcceptType.PilotArmor}
        path="system.loadout.armor.{armors.length}.value"
    />
{/if}
</HeaderMain>