export class NPCSheetSettingsSubmenu extends foundry.applications.api.HandlebarsApplicationMixin(
    foundry.applications.api.ApplicationV2
)
{
    static override DEFAULT_OPTIONS: foundry.applications.api.ApplicationV2.DefaultOptions = {
        id: "la-npc-settings-submenu",
        tag: "form",
        window: {
            title: "LA.SETTINGS.npc.label",
            icon: "fas fa-gear",
            contentClasses: ["standard-form"],
        },
        position: {
            width: 600,
        },
        form: {
            handler: NPCSheetSettingsSubmenu.#onSubmit,
            closeOnSubmit: true,
            submitOnChange: false,
        },
        actions: {
            resetServerData: NPCSheetSettingsSubmenu.#onResetServerData,
        },
    };

    static override PARTS: Record<string, foundry.applications.api.HandlebarsApplicationMixin.HandlebarsTemplatePart> = {
        body: {
            template: TEMPLATE_PATHS.npcSettingsSubmenu,
        },
        footer: {
            template: "templates/generic/form-footer.hbs",
        },
    };

    // Return type is `any` to work around the opaque generic RenderContext in the mixin
    protected override async _prepareContext(
        _options: object
    ): Promise<any>
    {
        return {
            tip: game.settings.get(LancerAlternative.Name, `npc-settings-tip`) as boolean,
            sheetWidth: game.settings.get(LancerAlternative.Name, `npc-settings-sheet-width`) as number,
            sheetHeight: game.settings.get(LancerAlternative.Name, `npc-settings-sheet-height`) as number,
            saveCollapse: game.settings.get(LancerAlternative.Name, `npc-settings-log-action-save-collapse`) as boolean,
            startCollapsed: game.settings.get(LancerAlternative.Name, `npc-settings-log-action-start-collapsed`) as boolean,
            isGM: game.user.isGM,
            buttons: [
                { type: "submit", icon: "fa-solid fa-floppy-disk", label: "SETTINGS.Save" },
            ],
        };
    }

    static #onResetServerData(
        this: NPCSheetSettingsSubmenu,
        _event: PointerEvent,
        _target: HTMLElement,
    ): void
    {
        if (!game.user.isGM) return;
        resetNPCSheetData();
    }

    static async #onSubmit(
        _event: SubmitEvent | Event,
        _form: HTMLFormElement,
        formData: foundry.applications.ux.FormDataExtended,
    ): Promise<void>
    {
        const data = formData.object;
        await Promise.all([
            game.settings.set(LancerAlternative.Name, `npc-settings-tip`, data["tip"] === true),
            game.settings.set(LancerAlternative.Name, `npc-settings-sheet-width`, Number(data["sheetWidth"])),
            game.settings.set(LancerAlternative.Name, `npc-settings-sheet-height`, Number(data["sheetHeight"])),
            game.settings.set(LancerAlternative.Name, `npc-settings-log-action-save-collapse`, data["saveCollapse"] === true),
            game.settings.set(LancerAlternative.Name, `npc-settings-log-action-start-collapsed`, data["startCollapsed"] === true),
        ]);
    }
}

export function registerNPCSheetSettings()
{
    // Public Settings
    game.settings.register(LancerAlternative.Name, `npc-settings-tip`, {
        name: "LA.SETTINGS.npc.enableTooltip.label",
        hint: "LA.SETTINGS.npc.enableTooltip.subLabel",
        scope: "client",
        config: false,
        type: Boolean,
        default: true,
    });

    game.settings.register(LancerAlternative.Name, `npc-settings-sheet-width`, {
        name: "LA.SETTINGS.npc.sheetWidth.label",
        hint: "LA.SETTINGS.npc.sheetWidth.subLabel",
        scope: "client",
        config: false,
        requiresReload: true,
        // @ts-ignore
        type: Number,
        default: 500,
    });

    game.settings.register(LancerAlternative.Name, `npc-settings-sheet-height`, {
        name: "LA.SETTINGS.npc.sheetHeight.label",
        hint: "LA.SETTINGS.npc.sheetHeight.subLabel",
        scope: "client",
        config: false,
        requiresReload: true,
        // @ts-ignore
        type: Number,
        default: 800,
    });

    game.settings.register(LancerAlternative.Name, `npc-settings-log-action-save-collapse`, {
        name: "LA.SETTINGS.npc.saveCollapse.label",
        hint: "LA.SETTINGS.npc.saveCollapse.subLabel",
        scope: "client",
        config: false,
        type: Boolean,
        default: false,
    });

    game.settings.register(LancerAlternative.Name, `npc-settings-log-action-start-collapsed`, {
        name: "LA.SETTINGS.npc.startCollapsed.label",
        hint: "LA.SETTINGS.npc.startCollapsed.subLabel",
        scope: "client",
        config: false,
        type: Boolean,
        default: true,
    });

    // Private Settings
    game.settings.register(LancerAlternative.Name, `_npc-settings`, {
        scope: "world",
        config: false,
        type: Array, // MessagePack encoded object
        default: [],
    });

    game.settings.register(LancerAlternative.Name, `_npc-settings-version`, {
        scope: "world",
        config: false,
        type: String,
        default: "",
    });

    // Sockets
    SocketManager.getInstance().register(setNPCSheetData);
}

// Client Settings
