<script lang="ts">
    import { TooltipFactory } from "@/classes/TooltipFactory";
    import { getLocalized } from "@/scripts/helpers";
    import { getCSSDocumentTheme, getCSSSystemTheme, getThemeName, convertToCSSTheme } from "@/scripts/theme";
    import { ThemeKey } from "@/enums/ThemeKey";
    import { TooltipDirection } from "@/enums/TooltipDirection";
    import type { ThemeOverrideButtonProps } from "@/interfaces/actor/button/ThemeOverrideButtonProps";
    import type { TextLogEventProps } from "@/interfaces/actor/TextLogEventProps";
    import type { IconButtonProps } from "@/interfaces/actor/button/IconButtonProps";
    import type { TooltipProps } from "@/interfaces/actor/TooltipProps";
    import { resetTextConsole, sendToTextConsole } from "@/scripts/store/text-log";
    import { getActorContext } from "@/scripts/context";

    const {
        uuid,
        disabled,
        setOverride,
        style,
        iconStyle,

        tooltipEnabled,
        tooltip,
        tooltipHeader,
        tooltipClass,
        tooltipDirection,
        
        logText,
        logging,
    }: ThemeOverrideButtonProps & IconButtonProps & TooltipProps & TextLogEventProps = $props();
    const actorUuid = getActorContext()?.uuid;
    let toggle = $state(false);
    let optionElement: HTMLElement | null = null;

    const tip = $derived(TooltipFactory.buildTooltip(tooltip || getLocalized("LA.advanced.themeOverride.tooltip"), tooltipHeader));
    const log = $derived(logText || getLocalized("LA.advanced.themeOverride.tooltip"));
    const theme = $derived(getCSSDocumentTheme(uuid));
    
    function handleOnClick(event: MouseEvent & { currentTarget: EventTarget & HTMLElement })
    {
        event.stopPropagation();
        if (toggle)
        {
            TooltipFactory.unrenderTooltip(optionElement);
            optionElement = null;
        }
        else
        {
            optionElement = TooltipFactory.renderTooltipSvelte(
                event,
                {
                    content: themeOverride,
                    unrenderCallback: () => { toggle = false; },
                },
                {
                    direction: TooltipDirection.DOWN,
                    cssClass: `la-tooltip -widthfull ${theme}`,
                    locked: true,
                }
            );
        }

        toggle = !toggle;
    }

    function handleThemeOverride(event: MouseEvent, theme: string)
    {
        event.stopPropagation();
        const selectedTheme = theme === "default" ? "" : theme;
        if (optionElement)
        {
            optionElement.classList.remove(getCSSDocumentTheme(uuid));
            if (selectedTheme)
                optionElement.classList.add(convertToCSSTheme(selectedTheme));
            else
                optionElement.classList.add(getCSSSystemTheme());
        }

        setOverride(uuid, selectedTheme);
    }
</script>

{#snippet themeOverride()}
    <div class="la-bckg-primary -fontsize4 -upper -padding0">
        {getLocalized("LA.advanced.themeOverride.tooltip")}<i class="mdi mdi-arrow-down-right"></i>
    </div>
    <div class="la-flexcol -widthfull -gap0 -padding0">
    {#each Object.values(ThemeKey) as theme}
        <button type="button"
            class="la-bckg-scrollbar-secondary la-text-header -fontsizemedium -letterspacing0 la-prmy-secondary -glow-prmy-hover -widthfull"
            onclick={event => handleThemeOverride(event, theme)}
        >
            {getThemeName(theme)}
        </button>
    {/each}
        <button type="button"
            class="la-bckg-scrollbar-secondary la-text-header -fontsizemedium -letterspacing0 la-prmy-secondary -glow-prmy-hover la-scdy-accent -glow-scdy-focus -widthfull"
            onclick={event => handleThemeOverride(event, "default")}
        >
            {getLocalized("LA.advanced.theme.default.label")}
        </button>
    </div>
{/snippet}

{#if !disabled}
<button type="button"
    class="{style?.join(' ')} la-prmy-primary -glow-prmy-hover"
    data-tooltip={tooltipEnabled ? tip : undefined }
    data-tooltip-class={`${tooltipClass || "clipped-bot la-tooltip"} ${theme}`}
    data-tooltip-direction={tooltipDirection || TooltipDirection.UP}
    onpointerenter={ logging ? event => sendToTextConsole(event, log, actorUuid!) : undefined }
    onpointerleave={ logging ? event => resetTextConsole(event, actorUuid!) : undefined }
    onclick={event => handleOnClick(event)}
    aria-label={getLocalized("LA.advanced.themeOverride.tooltip")}
>
    <i class="mdi mdi-notebook-edit {iconStyle?.join(' ') || 'la-text-header -fontsize5'}"></i>
</button>
{/if}