<script lang="ts">
    import { ActiveTab } from "@/enums/ActiveTab";
    import { FlowClass } from "@/enums/FlowClass";
    import type { MechSheetProps } from "@/interfaces/mech/MechSheetProps";
    import { getActiveTab, getAdvancedState } from "@/scripts/store/advanced";
    import { getLocalized } from "@/scripts/helpers";
    import { getMechSheetTooltipEnabled } from "@/scripts/mech/settings";
    import { getCSSDocumentTheme } from "@/scripts/theme";
    // import InventoryButton from "@/svelte/shared/button/InventoryButton.svelte";
    import { SETTINGS_BUTTON_STYLE, SETTINGS_HEADER_STYLE } from "@/svelte/mech/settings/AdvancedSettings.svelte";
    import GlyphButton from "@/svelte/shared/button/GlyphButton.svelte";
    import { TooltipDirection } from "@/enums/TooltipDirection";
    
    const props: MechSheetProps = $props();
    const {
        actor,
    } = $derived(props);

    const tooltipEnabled = getMechSheetTooltipEnabled();
    const advancedOptions = $derived(getAdvancedState(actor.uuid));
    const active = $derived(getActiveTab(actor.uuid, ActiveTab.Primary) || "loadout");// This is set to match the initial tab on the sheet setup
    const theme = $derived(getCSSDocumentTheme(actor.uuid));
</script>

<div class="-heightfull
    {advancedOptions && active === 'loadout' ? 'la-flexrow' : '-displaynone'}"
>
    <span class="{SETTINGS_HEADER_STYLE()} -alignend">
        {getLocalized("LA.advanced.inventory.label")}
    </span>
    <div class="la-flexcol -alignstart -padding0-b -heightfull">
        <!-- This div is what actually triggers the inventory event from the Lancer system -->
        <div class="inventory">
            <GlyphButton
                style={[SETTINGS_BUTTON_STYLE(), "mdi mdi-archive -widthfull -heightfull"]}
                
                flowClass={FlowClass.Inventory}
                
                tooltipEnabled={tooltipEnabled}
                tooltipTheme={theme}
                tooltip={getLocalized("LA.advanced.inventory.open.tooltip")}
                tooltipDirection={TooltipDirection.RIGHT}
                logging={true}
            ></GlyphButton>
        </div>
    </div>
</div>