<script lang="ts">
    import { getLocalized, randomExtension } from "@/scripts/helpers";
    import { resetTextConsole, sendToTextConsole } from "@/scripts/store/text-log";
    import { getActorContext } from "@/scripts/context";
    import { TooltipFactory } from "@/classes/TooltipFactory";

    import TerminalText, { FLOW_BUTTON_STYLE } from "@/svelte/shared/TerminalText.svelte";

    import type { ButtonProps } from "@/interfaces/actor/button/ButtonProps";
    import type { TerminalTextProps } from "@/interfaces/actor/TerminalTextProps";
    import type { TooltipProps } from "@/interfaces/actor/TooltipProps";
    import type { TextLogEventProps } from "@/interfaces/actor/TextLogEventProps";
    import type { IconButtonProps } from "@/interfaces/actor/button/IconButtonProps";

    const {
        style,
        onClick,

        uuid,
        flowType,
        flowArgs,
        flowClass,
        path,
        
        text,
        textStyle,

        tooltipEnabled,
        tooltipHeader,
        tooltip,
        tooltipDirection,
        tooltipClass,
        tooltipTheme,

        disableSlide,
        disableCmdline,
        disableExtension,
        disableCursor,

        logText,
        logging,
    } : IconButtonProps & ButtonProps & TooltipProps & TerminalTextProps & TextLogEventProps = $props();
    const actorUuid = getActorContext()?.uuid;

    const tip = $derived(TooltipFactory.buildTooltip(tooltip || getLocalized("LA.flow.tooltip"), tooltipHeader));
    const log = $derived(logText || getLocalized("LA.flow.tooltip"));
</script>
<script lang="ts" module>
    export const FLOW_BUTTON_DEFAULT = () => " clipped-bot-alt la-bckg-secondary -widthfull -overflowhidden -lineheight3 -padding0-lr ";
</script>

<button 
    type="button"
    class="-upper
        {disableSlide || 'la-flow'} 
        {style?.join(' ') || FLOW_BUTTON_DEFAULT()}
        {flowClass || ''}"
    data-uuid={uuid}
    data-flow-type={flowType}
    data-flow-args={flowArgs}
    data-path={path}
    data-tooltip={tooltipEnabled ? tip : undefined }
    data-tooltip-class={`${tooltipClass || "clipped-bot la-tooltip"} ${tooltipTheme}`}
    data-tooltip-direction={tooltipDirection || 'RIGHT'}
    onpointerenter={ logging ? event => sendToTextConsole(event, log, actorUuid!) : undefined }
    onpointerleave={ logging ? event => resetTextConsole(event, actorUuid!) : undefined }
    onclick={(event) => onClick && onClick(event)}
    aria-label={text}
>
    <TerminalText
        text={text}
        extensionText={randomExtension()}
        textStyle={textStyle || [FLOW_BUTTON_STYLE]}
        disableCmdline={disableCmdline}
        disableExtension={disableExtension}
        disableCursor={disableCursor}
    />
</button>