<script lang="ts">
    import { CounterBoxType } from "@/enums/CounterBoxType";
    import type { CounterBoxProps } from "@/interfaces/actor/CounterBoxProps";
    import type { PointerClickProps } from "@/interfaces/actor/events/PointerClickProps";
    import type { TextLogEventProps } from "@/interfaces/actor/TextLogEventProps";
    import { getLocalized, logographicLanguage } from "@/scripts/helpers";
    import { resetTextConsole, sendToTextConsole } from "@/scripts/store/text-log";
    import { getActorContext } from "@/scripts/context";
    import { getExtraEffectsEnabled } from "@/scripts/settings";

    const {
        text,
        type,
        usesValue,
        usesMax,
        path,
        style,
        
        logText,
        logging,

        onPointerClick,
    }: CounterBoxProps & TextLogEventProps & PointerClickProps = $props();
    const actorUuid = getActorContext()?.uuid;

    const qualityMode = getExtraEffectsEnabled();
    const log = $derived(logText || getLocalized("LA.counter.tooltip"));

    function handleOnClick(event: MouseEvent & { currentTarget: EventTarget & HTMLElement }, index: number)
    {
        event.stopPropagation();

        if (onPointerClick)
            onPointerClick(event, index);
    }
</script>
<script lang="ts" module>
    const _COUNTER_STYLE = "clipped-alt -widthfull la-bckg-header-anti"
</script>

{#if usesMax}
<div 
    class="la-counterbox la-flexrow -aligncenter la-text-header -padding1-lr
        {style?.join(' ') || type === CounterBoxType.Counter ? _COUNTER_STYLE : ''}"
>
{#if text}
    <span class="la-counterbox__span {logographicLanguage() ? '-fontsize3' : '-fontsizemedium'}">
        {text}
    </span>
{/if}
{#each {length: usesMax} as _, index}
    <button type="button"
        class="la-counterbox__button
            mdi {index < usesValue ? 'mdi-hexagon-slice-6' : 'mdi-hexagon-outline'}
            la-prmy-header la-scdy-primary -fontsize7
            {qualityMode ? '-glow-prmy -glow-scdy-hover' : ''}
            {type}"
        data-available={index < usesValue}
        data-path={path}
        onpointerenter={ logging ? event => sendToTextConsole(event, log, actorUuid!) : undefined }
        onpointerleave={ logging ? event => resetTextConsole(event, actorUuid!) : undefined }
        onclick={event => handleOnClick(event, index)}
        aria-label="{getLocalized('LA.use.label')} {text}"
    ></button>
{/each}
</div>
{/if}