<script lang="ts">
    import { TooltipFactory } from "@/classes/TooltipFactory";
    import { getLocalized } from "@/scripts/helpers";
    import { getPilotSheetTooltipEnabled } from "@/scripts/pilot/settings";
    import { getCSSDocumentTheme } from "@/scripts/theme";
    import { TooltipDirection } from "@/enums/TooltipDirection";
    import { FlowClass } from "@/enums/FlowClass";
    import { CounterBoxType } from "@/enums/CounterBoxType";
    
    import HeaderMain, { MAIN_HEADER_STYLE } from "@/svelte/shared/header/HeaderMain.svelte";
    import HeaderSecondary, { H2_HEADER_STYLE, H2_TEXT_SIZE } from "@/svelte/shared/header/HeaderSecondary.svelte";
    import GlyphButton from "@/svelte/shared/button/GlyphButton.svelte";
    import CounterBox from "@/svelte/shared/counter/CounterBox.svelte";
    import EmptyBox from "@/svelte/shared/EmptyBox.svelte";
    import { H2_BUTTON_ICON_STYLE } from "@/svelte/shared/button/Button.svelte";
    import { getExtraEffectsEnabled } from "@/scripts/settings";

    const {
        actor,
        system,
    } = $props();
    let editButtonHover = $state(false);
    let addButtonHover = $state(false);

    const tooltipEnabled = getPilotSheetTooltipEnabled();
    const qualityMode = getExtraEffectsEnabled();
    const collID = $derived(`${actor.uuid}.burdens`);
    const burdens = $derived(system.bond_state.burdens);
    const theme = $derived(getCSSDocumentTheme(actor.uuid));

    const addBurdenTip = TooltipFactory.buildTooltip(getLocalized("LA.pilot.bond.burden.add.tooltip"))
    
    function getBurdenPath(index: number)
    {
        return `system.bond_state.burdens.${index}`;
    }
</script>

{#if system.bond}
{#snippet headerContent()}
<GlyphButton
    style={["mdi mdi-plus-circle-outline -fontsize5 -height4 -lineheight4 la-prmy-header la-scdy-primary",
        qualityMode ? "-glow-prmy -glow-scdy-hover" : ""]}

    flowClass={FlowClass.GeneralControl}
    path="system.bond_state.burdens"
    action="append"
    actionValue="(struct)counter"

    tooltipEnabled={tooltipEnabled}
    tooltipTheme={theme}
    tooltip={addBurdenTip}
    tooltipDirection={TooltipDirection.UP}
    logText={getLocalized("LA.pilot.bond.burden.add.tooltip")}
    logging={true}

    disabled={system.bond === null}

    onPointerEnter={() => {addButtonHover = true;}}
    onPointerLeave={() => {addButtonHover = false;}}
/>
{/snippet}
<HeaderMain
    text={getLocalized("LA.pilot.bond.burden.label")}
    headerStyle={[MAIN_HEADER_STYLE, "la-bckg-weapon"]}
    textStyle={["la-text-header -fontsize4 -overflowhidden"]}
    borderStyle={["la-brdr-weapon"]}
    extensionTextFunction={() => {
        if (addButtonHover)
            return `--${getLocalized("LA.add.extension")}`;
        return undefined;
    }}
    
    collapseID={collID}
    startCollapsed={true}

    headerContent={headerContent}
>
{#if burdens.length}
    <div class="la-generated -widthfull -gap1 la-flexcol">
    {#each burdens as burden, index}
        <div class="la-flexcol -widthfull -fontface-stylized">
        {#snippet outerContent()}
            <div class="-padding2-l">
                <CounterBox
                    type={CounterBoxType.Counter}
                    usesValue={burden.value}
                    usesMax={burden.max}
                    path="system.bond_state.burdens.{index}"
                    style={["clipped-bot-alt -widthfull la-bckg-header-anti"]}
                    
                    logging={true}
                />
            </div>
        {/snippet}
        {#snippet headerSecondaryLeftOptions()}
            <i class="mdi mdi-weather-night -fontsize5 -padding0-lr"></i>
        {/snippet}
        {#snippet headerSecondaryRightOptions()}
            <!-- Edit -->
            <GlyphButton
                style={[H2_BUTTON_ICON_STYLE(), "-padding0-lr"]}
                flowClass={FlowClass.ContextMenu}
                path={getBurdenPath(index)}

                tooltipEnabled={tooltipEnabled}
                tooltipDirection={TooltipDirection.UP}
                tooltipTheme={theme}
                tooltip={getLocalized("LA.edit.tooltip")}
                logText={getLocalized("LA.edit.tooltip")}
                logging={true}

                onPointerEnter={() => {editButtonHover = true;} }
                onPointerLeave={() => {editButtonHover = false;} }
            >
                <i class="fas fa-ellipsis-v"></i>
            </GlyphButton>
        {/snippet}
            <HeaderSecondary
                text={burden.name}
                headerStyle={[H2_HEADER_STYLE, "la-bckg-pilot"]}
                textStyle={[H2_TEXT_SIZE, "-overflowhidden -fontface-stylized"]}
                borderStyle={["-bordersoff"]}
                extensionTextFunction={() => {
                    if (editButtonHover)
                        return `--${getLocalized("LA.edit.extension")}`;
                    return undefined;
                }}

                itemID={burden.lid}
                uuid={burden.uuid}

                renderOutsideCollapse={outerContent}
                contentLeft={headerSecondaryLeftOptions}
                contentRight={headerSecondaryRightOptions}
            >
            </HeaderSecondary>
        </div>
    {/each}
    </div>
{:else}
    <EmptyBox
        label={getLocalized("LA.pilot.bond.burden.empty.label")}
        subLabel={getLocalized("LA.pilot.bond.burden.empty.subLabel")}
    />
{/if}
</HeaderMain>
{/if}