<script lang="ts">
    import { FlowClass } from "@/enums/FlowClass";
    import { TooltipDirection } from "@/enums/TooltipDirection";
    import { getBondQNAMode, setBondQNAMode } from "@/scripts/store/bond";
    import { getLocalized, logographicLanguage } from "@/scripts/helpers";
    import { getBondImageSrc, getPilotSheetTooltipEnabled, setBondImageSrc } from "@/scripts/pilot/settings";
    import { getAdvancedState } from "@/scripts/store/advanced";
    import { getThemeKey } from "@/scripts/store/theme";
    import { getBrightness, getCSSDocumentTheme } from "@/scripts/theme";
    import StatusBar from "@/svelte/shared/StatusBar.svelte";
    import FlowButton from "@/svelte/shared/button/FlowButton.svelte";
    import GlyphButton from "@/svelte/shared/button/GlyphButton.svelte";
    import { getExtraEffectsEnabled } from "@/scripts/settings";

    const {
        actor,
        system,
    } = $props();
    // svelte-ignore state_referenced_locally
    let bondImageSrc = $state(getBondImageSrc(actor.uuid));

    const logographic = logographicLanguage();
    const tooltipEnabled = getPilotSheetTooltipEnabled();
    const qualityMode = getExtraEffectsEnabled();
    const advancedOptions = $derived(getAdvancedState(actor.uuid));
    const questionAnswer = $derived(getBondQNAMode(actor.uuid));
    const theme = $derived(getCSSDocumentTheme(actor.uuid));
    const darkTheme = $derived(getBrightness(getThemeKey(actor.uuid)) === "dark");

    function getGlowColor()
    {
        return darkTheme ? "la-prmy-text" : "la-prmy-primary";
    }

    function browseImage()
    {
        const fp = new FilePicker({
            current: bondImageSrc,
            type: "image",
            callback: (path) => {
                setBondImageSrc(actor.uuid, path);
                bondImageSrc = path;
            },
        });

        fp.render(true);
    }

    function tallyAndUpdate(event: Event)
    {
        event.stopPropagation();

        let expTotal = 0;

        // Tally XP from the checklist
        const updatedMajorIdeals = system.bond_state.xp_checklist.major_ideals.map((major: boolean) => 
        {
            if (major === true) expTotal++;
            return false;
        });
        if (system.bond_state.xp_checklist.minor_ideal === true)
            expTotal++;
        if (system.bond_state.xp_checklist.veteran_power === true)
            expTotal++;

        // Update XP and set their checked state to false
        if (expTotal > 0)
            actor.update({
                ["system.bond_state.xp.value"]: system.bond_state.xp.value + expTotal,
                ["system.bond_state.xp_checklist"]: {
                    major_ideals: updatedMajorIdeals,
                    minor_ideal: false,
                    veteran_power: false,
                },
            });
    }

    function editBond(event: Event)
    {
        event.stopPropagation();

        const doc = fromUuidSync(system.bond.uuid) as any | null; //AdDpOl0s3D8U97HW
        if (doc)
        {
            const sheet = doc.sheet;
            if (sheet?.rendered)
                sheet.maximize().then(() => sheet!.bringToTop())
            else sheet?.render(true);
        }
    }

    function removeBond(event: Event)
    {
        event.stopPropagation();

        const doc = fromUuidSync(system.bond.uuid) as any | null;

        if (doc)
        {
            // Eh... if they accidentally remove it then that's on them
            doc.delete();
        }
    }
</script>

{#if system.bond}
<div class="la-flexcol -widthfull -margin1-b -padding1-tb la-reveal-hover
        {qualityMode ? 'la-bg-scroll-alt' : 'la-bg-alt'}"
>
    <!-- Remove Bond -->
    <GlyphButton
        style={["mdi mdi-close-thick la-text-error -fontsize6 -lineheight8 -justifycenter -aligncenter -positionabsolute -left2",
            advancedOptions ? '' : '-visibilityhidden',
            qualityMode ? " la-prmy-primary -glow-prmy-hover " + getGlowColor() : ""]}

        flowClass={FlowClass.None}
        onClick={removeBond}

        tooltipEnabled={tooltipEnabled}
        tooltipTheme={theme}
        tooltip={getLocalized("LA.delete.tooltip")}
        logText={getLocalized("LA.delete.tooltip")}
        logging={true}
    />
    <!-- Bond Name -->
    <span class="-fontsize6 -letterspacing1 -upper">
        {system.bond.name}
    </span>
    <!-- Bond XP -->
    <div class="-widthhalf -padding0-tb -fontface-stylized">
        <StatusBar
            dataName={"system.bond_state.xp.value"}
            nameStyle={[logographic ? "-fontsizemedium" : ""]}
            currentValue={system.bond_state.xp.value}
            maxValue={system.bond_state.xp.max}
            barStyle={["la-bckg-bar-health"]}
            barStyleSecondary={["la-bckg-bar-shield -shield"]}
            barStyleTertiary={["la-bckg-bar-burn -burn"]}
            textStyle={["la-text-text"]}
            clipPath={"clipped"}

            tooltipEnabled={tooltipEnabled}
            tooltip={getLocalized("LA.hitpoint.tooltip")}
            tooltipDirection={TooltipDirection.RIGHT}
        />
    </div>
    <div
        class="la-flexrow -positionrelative -widthfull -aligncenter
            {qualityMode ? 'la-bond-card-spin' : 'la-bond-card'}"
    >
        <!-- Bond Image -->
        <div class="la-bond-card__img-anchor -margin7-tb"
        >
            <img
                class="la-bond-card__img"
                src={bondImageSrc}
                alt={getLocalized("LA.placeholder")}
            />
        </div>
    {#if !questionAnswer}
        <div class="la-bond-card__content la-flexcol -positionabsolute -margin0-tb -heightfull -justifyevenly la-reveal">
            <!-- Major Ideals -->
            <div class="la-bond-major la-flexcol -alignstart clipped -widthfull -padding0 -padding1-r
                    {darkTheme ? 'la-bckg-darken-1' : 'la-bckg-lighten-5' }"
            >
            {#each system.bond.system.major_ideals as major, index}
                <div class="la-flexrow">
                    <input type="checkbox"
                        class=""
                        name="system.bond_state.xp_checklist.major_ideals.{index}"
                        checked={system.bond_state.xp_checklist.major_ideals[index]}
                    />
                    <span
                        class="-fontsizemedium -lineheight5 -padding0-lr"
                    >
                        {major}
                    </span>
                </div>
            {/each}
            </div>
            <!-- Minor Ideals -->
            <div class="la-bond-minor la-flexcol -alignstart clipped -widthfull -padding0 -padding1-r
                    {darkTheme ? 'la-bckg-darken-1' : 'la-bckg-lighten-5' }"
            >
                <div class="la-flexrow -widthfull">
                    <input type="checkbox"
                        class=""
                        name="system.bond_state.xp_checklist.minor_ideal"
                        checked={system.bond_state.xp_checklist.minor_ideal}
                    />
                    <select
                        class="la-bond__select -fontsizemedium -lineheight5 la-bckg-transparent la-text-text -widthfull"
                        name="system.bond_state.minor_ideal" 
                        data-type="String"
                    >
                    {#each system.bond.system.minor_ideals as minor}
                        <option
                            style="color: black"
                            value="{minor}"
                            selected={minor === system.bond_state.minor_ideal}
                        >
                            {minor}
                        </option>
                    {/each}
                    </select>
                </div>
                <div class="la-flexrow">
                    <input type="checkbox"
                        class=""
                        name="system.bond_state.xp_checklist.veteran_power"
                        checked={system.bond_state.xp_checklist.veteran_power}
                    />
                    <span
                        class="-fontsizemedium -lineheight5 -padding0-lr"
                    >
                        {getLocalized("LA.pilot.bond.other.label")}
                    </span>
                </div>
            </div>
        </div>
    {:else}
        <div class="la-bond-card__content la-flexcol -positionabsolute -margin0-tb -heightfull -justifyevenly la-reveal">
            <!-- Q&A -->
            {#each system.bond.system.questions as qna, index}
            <div class="la-bond-question la-flexcol -alignstart clipped -widthfull -padding2-lr -padding0-t -padding1-b
                        {darkTheme ? 'la-bckg-darken-1' : 'la-bckg-lighten-5' }">
                <span
                    class="-fontsizemedium -lineheight5"
                >
                    {qna.question}
                </span>
                <select 
                    class="la-bond__select -fontsizemedium -lineheight5 la-bckg-transparent la-text-text"
                    name="system.bond_state.answers.{index}" 
                    data-type="String"
                >
                {#each qna.options as answer}
                    <option
                        value="{answer}"
                        selected={answer === system.bond_state.answers[index]}
                    >
                        {answer}
                    </option>
                {/each}
                </select>
            </div>
            {/each}
        </div>
    {/if}
    </div>
    <div class="la-flexrow">
    <!-- Bond XP Tally -->
        <FlowButton
            text={getLocalized("LA.pilot.bond.tally.label")}
            style={["clipped la-bckg-secondary -padding0-tb -flex1"]}

            flowClass={FlowClass.None}

            tooltipEnabled={tooltipEnabled}
            tooltipTheme={theme}
            tooltipDirection={TooltipDirection.DOWN}
            tooltip={getLocalized("LA.pilot.bond.tally.tooltip")}
            logText={getLocalized("LA.pilot.bond.tally.tooltip")}
            logging={true}

            onClick={tallyAndUpdate}
        />
        <div class="la-flexrow -positionabsolute -right0 -padding3-r -gap2 {advancedOptions ? '' : '-visibilityhidden'}">
            <!-- Edit Bond Image -->
            <GlyphButton
                style={["mdi mdi-image-edit la-text-secondary -fontsize7 la-flexrow -justifycenter -aligncenter",
                    qualityMode ? " la-prmy-primary -glow-prmy-hover " + getGlowColor() : ""]}

                flowClass={FlowClass.None}

                tooltipEnabled={tooltipEnabled}
                tooltipTheme={theme}
                tooltip={getLocalized("LA.pilot.bond.changeImage.tooltip")}
                logText={getLocalized("LA.pilot.bond.changeImage.tooltip")}
                logging={true}

                onClick={browseImage}
            />
            <!-- Edit Bond -->
            <GlyphButton
                style={["mdi mdi-file-document-edit la-text-secondary -fontsize6 -lineheight8 -justifycenter -aligncenter",
                    qualityMode ? " la-prmy-primary -glow-prmy-hover " + getGlowColor() : ""]}

                flowClass={FlowClass.None}
                onClick={editBond}

                tooltipEnabled={tooltipEnabled}
                tooltipTheme={theme}
                tooltip={getLocalized("LA.edit.tooltip")}
                logText={getLocalized("LA.edit.tooltip")}
                logging={true}
            />
        </div>
        <div class="la-flexrow -positionabsolute -left0 -padding3-l -gap1">
            <!-- Q&A Toggle -->
            <i class="mdi mdi-swap-vertical -fontsize la-text-text -positionabsolute -left0
                {qualityMode ? '-glow-prmy la-prmy-primary -glow-prmy-hover' + getGlowColor() : ''}"
            ></i>
            <GlyphButton
                style={["la-text-secondary -fontsize7 la-flexrow -justifycenter -aligncenter",
                    questionAnswer ? "mdi mdi-list-box" : "mdi mdi-help-circle",
                    qualityMode ? " la-prmy-primary -glow-prmy-hover " + getGlowColor() : ""]}

                flowClass={FlowClass.None}

                tooltipEnabled={tooltipEnabled}
                tooltipTheme={theme}
                tooltip={getLocalized("LA.pilot.bond.swap.tooltip")}
                logText={getLocalized(!questionAnswer ? "LA.pilot.bond.qa.tooltip" : "LA.pilot.bond.xp.tooltip")}
                logging={true}

                onClick={() => { setBondQNAMode(actor.uuid, !questionAnswer); }}
            />
            <!-- Refresh Powers -->
            <GlyphButton
                style={["mdi mdi-refresh-circle la-text-secondary -fontsize7 -justifycenter",
                    qualityMode ? " la-prmy-primary -glow-prmy-hover " + getGlowColor() : ""]}

                flowClass={FlowClass.BondPowerRefresh}

                tooltipEnabled={tooltipEnabled}
                tooltipTheme={theme}
                tooltip={getLocalized("LA.pilot.bond.power.refresh.tooltip")}
                logText={getLocalized("LA.pilot.bond.power.refresh.tooltip")}
                logging={true}

                onClick={() => { setBondQNAMode(actor.uuid, !questionAnswer); }}
            />
        </div>
    </div>
</div>
{/if}