<script lang="ts">
    import type { MechSheetProps } from "@/interfaces/mech/MechSheetProps";
    import { getCSSDocumentTheme, getManufacturerColor } from "@/scripts/theme";
    import { slugify } from "@/scripts/lancer/util/lid";
    import { ACTIVATION_COLOR_MAP, ACTIVATION_ICON_MAP, ACTIVATION_LOCALIZE_MAP, ACTIVATION_TOOLTIP_LOCALIZE_MAP } from "@/scripts/constants";
    import { getLocalized } from "@/scripts/helpers";
    import { getMechSheetTooltipEnabled } from "@/scripts/mech/settings";
    import { TooltipFactory } from "@/classes/TooltipFactory";
    import { TooltipDirection } from "@/enums/TooltipDirection";
    import { FlowClass } from "@/enums/FlowClass";
    import ActionBox from "@/svelte/shared/ActionBox.svelte";
    import DeployableBox from "@/svelte/shared/DeployableBox.svelte";
    import EffectBox from "@/svelte/shared/EffectBox.svelte";
    import HeaderQuinary, { H4_BORDER_STYLE } from "@/svelte/shared/header/HeaderQuinary.svelte";
    import EffectButton from "@/svelte/shared/button/EffectButton.svelte";
    import { H2_ICON_SIZE } from "@/svelte/shared/header/HeaderSecondary.svelte";
    import { getExtraEffectsEnabled } from "@/scripts/settings";

    const {
        actor,
        system,
    }: MechSheetProps = $props();
    const tooltipEnabled = getMechSheetTooltipEnabled();
    const qualityMode = getExtraEffectsEnabled();

    const frame = $derived(system.loadout.frame!.value);
    const core = $derived(frame.system.core_system);
    const collID = $derived(`${actor.uuid}.${frame.id}.activePower`);
    const actionCollID = $derived(`${actor.uuid}.${frame.id}.activePower.action`);
    const name = $derived(core.active_actions.length ? core.active_actions[0].name : getLocalized("LA.activate.label"));
    const activationClass = $derived(`activation-${slugify(core.activation, "-")}`);
    const activationTheme = $derived(system.core_energy
        ? `${ACTIVATION_COLOR_MAP[core.activation]}`
        : "la-bckg-repcap");
    const frameColorBckg = $derived(getManufacturerColor(frame.system.manufacturer, "bckg"));
    const frameColorBrdr = $derived(system.core_energy
        ? getManufacturerColor(frame.system.manufacturer, "brdr")
        : "la-brdr-repcap");
    const tip = $derived(TooltipFactory.buildTooltip(
        getLocalized([core.active_effect, ACTIVATION_TOOLTIP_LOCALIZE_MAP[core.activation]]),
        getLocalized(ACTIVATION_LOCALIZE_MAP[core.activation])));
    const theme = $derived(getCSSDocumentTheme(actor.uuid));
</script>

<!-- Frame Active -->
{#if core.active_effect || core.active_actions.length || core.active_bonuses.length }
{#snippet headerQuinaryLeftOptions()}
<EffectButton
    iconStyle={[H2_ICON_SIZE, "cci", ACTIVATION_ICON_MAP[core.activation]]}
    iconBackgroundStyle={[H2_ICON_SIZE, "la-prmy-secondary",
        qualityMode ? "-pulse-prmy" : "la-text-scrollbar-secondary"]}
    
    flowClass={FlowClass.None}
    
    tooltipEnabled={tooltipEnabled}
    tooltipTheme={theme}
    tooltipDirection={TooltipDirection.LEFT}
    tooltipHeader={getLocalized(ACTIVATION_LOCALIZE_MAP[core.activation])}
    logging={true}

    disabled={system.core_energy === 0}
/>
{/snippet}
{#snippet outerContent()}
<div class="la-spacer -medium"></div>
<div
    class="la-flexrow -widthfull
        {system.core_energy && qualityMode ? 'la-prmy-primary -glow-prmy-hover' : ''}"
>
    <button type="button"
        class="la-corepower clipped la-text-header la-flexrow -padding0-tb -fontsize5 -lineheight7 -widthfull
            {activationTheme} {system.core_energy ? '' : 'la-dropshadow -disabled'}
            activation-flow {activationClass}"
        data-uuid={frame.uuid}
        data-path={"system.core_system"}
        data-tooltip={tip}
        data-tooltip-class="clipped-bot la-tooltip {theme}"
        data-tooltip-direction={TooltipDirection.LEFT}
        aria-label={name}
        disabled={!system.core_energy}
    >
        <i class="la-corepower__i cci cci-activate la-dropshadow -flexthird -textalignleft -height7 -lineheight7 -fontsize19"></i>
        <span class="la-corepower__span -upper -flexthird -textwrapnowrap
            {system.core_energy ? 'la-prmy-header la-scdy-primary' : 'la-dropshadow'}
            {qualityMode ? '-glow-prmy -glow-scdy-hover' : ''}"
        >
            {name}
        </span>
        <span class="-flexthird">
        </span>
    </button>
</div>
{/snippet}
<HeaderQuinary
    text={core.name}
    headerStyle={[frameColorBckg, "la-text-header la-prmy-header -padding0-l"]}
    borderStyle={[H4_BORDER_STYLE, frameColorBrdr]}
    textStyle={["-fontface-stylized"]}

    collapseID={collID}

    renderOutsideCollapse={outerContent}
    contentLeft={headerQuinaryLeftOptions}
>
    <div class="la-divider-h la-bckg-primary -margin0-tb -margin2-b"></div>
    <div class="la-generated -widthfull -gap1 la-flexcol">
        <EffectBox
            name={getLocalized(ACTIVATION_LOCALIZE_MAP[core.activation])}
            effect={core.active_effect}

            tooltipEnabled={tooltipEnabled}
            logging={true}
        />
        <ActionBox
            uuid={frame.uuid}
            actions={core.active_actions}
            actor={actor}
            path={'system.core_system.active_actions'}

            collapseID={actionCollID}
            startCollapsed={false}

            tooltipEnabled={tooltipEnabled}
            tooltipTheme={theme}
            logging={true}
        />
        <DeployableBox
            source={actor}
            lidSource={core}
            uuid={frame.uuid}
            sheetUUID={actor.uuid}

            tooltipEnabled={tooltipEnabled}
            tooltipTheme={theme}
            logging={true}
        />
    </div>
</HeaderQuinary>
{/if}