<script lang="ts">
    import { getLocalized } from "@/scripts/helpers";
    import { getPilotSheetTooltipEnabled } from "@/scripts/pilot/settings";
    import { getCSSDocumentTheme } from "@/scripts/theme";
    import { FlowClass } from "@/enums/FlowClass";
    import { CounterBoxType } from "@/enums/CounterBoxType";
    import { AcceptType } from "@/enums/AcceptType";
    import { TooltipDirection } from "@/enums/TooltipDirection";

    import HeaderMain, { MAIN_HEADER_STYLE } from "@/svelte/shared/header/HeaderMain.svelte";
    import HeaderSecondary, { H2_HEADER_STYLE, H2_ICON_SIZE, H2_TEXT_SIZE } from "@/svelte/shared/header/HeaderSecondary.svelte";
    import EffectBox from "@/svelte/shared/EffectBox.svelte";
    import TagArray from "@/svelte/shared/TagArray.svelte";
    import CollapseAllButton from "@/svelte/shared/button/CollapseAllButton.svelte";
    import GlyphButton from "@/svelte/shared/button/GlyphButton.svelte";
    import ActionBox from "@/svelte/shared/ActionBox.svelte";
    import DeployableBox from "@/svelte/shared/DeployableBox.svelte";
    import BonusBox from "@/svelte/shared/BonusBox.svelte";
    import CounterBox from "@/svelte/shared/counter/CounterBox.svelte";
    import LimitedBox from "@/svelte/shared/counter/LimitedBox.svelte";
    import EmptyBox from "@/svelte/shared/EmptyBox.svelte";
    import { H2_BUTTON_ICON_STYLE } from "@/svelte/shared/button/Button.svelte";

    const {
        actor,
        gears
    } = $props();
    let collapseAllButtonHover = $state(false);
    let editButtonHover = $state(false);
    let messageButtonHover = $state(false);

    const tooltipEnabled = getPilotSheetTooltipEnabled();
    const collID = $derived(`${actor.uuid}.gears`);
    const theme = $derived(getCSSDocumentTheme(actor.uuid));

    function getGearPath(index: number)
    {
        return `system.loadout.gear.${index}.value`;
    }

    function renderOuter(gear: any)
    {
        return gear.system.uses.max || gear.system.counters.length;
    }
</script>

{#snippet headerOptions()}
<CollapseAllButton
    collapseID={collID}
    tooltipEnabled={tooltipEnabled}
    tooltipTheme={theme}

    onPointerEnter={() => {collapseAllButtonHover = true;}}
    onPointerLeave={() => {collapseAllButtonHover = false;}}
/>
{/snippet}

<HeaderMain
    text={getLocalized("LA.pilot.gear.label")}
    headerStyle={[MAIN_HEADER_STYLE, "la-bckg-system"]}
    textStyle={["la-text-header -fontsize4 -overflowhidden"]}
    borderStyle={["la-brdr-system"]}
    extensionTextFunction={() => {
        if (collapseAllButtonHover)
            return `--${getLocalized("LA.collapseAll.extension")}`;
        return undefined;
    }}
    
    collapseID={collID}
    startCollapsed={true}
    
    headerContent={headerOptions}
>
{#if gears.length}
    <div class="la-flexcol -gap0 -widthfull">
    {#each gears as gear, index}
    {#snippet outerContent()}
        <div class="la-flexcol -gap0 -widthfull -padding2-l -fontface-stylized">
        {#if gear.system.uses.max}
            <div class="la-flexrow clipped-bot-alt la-bckg-header-anti -widthfull">
                <!-- Limited -->
                <LimitedBox
                    usesValue={gear.system.uses.value}
                    usesMax={gear.system.uses.max}
                    path={getGearPath(index)}
        
                    logging={true}
                />
            </div>
        {/if}
        <!-- Counters -->
        {#if gear.system.counters.length}
        {#each gear.system.counters as counter, jndex}
            <CounterBox
                text={counter.name}
                type={CounterBoxType.Counter}
                usesValue={counter.value}
                usesMax={counter.max}
                path="{getGearPath(index)}.system.counters.{jndex}"
        
                logging={true}
            />
        {/each}
        {/if}
        </div>
    {/snippet}
    {#snippet headerSecondaryLeftOptions()}
        <i class="{H2_ICON_SIZE} cci cci-system"></i>
    {/snippet}
    {#snippet headerSecondaryRightOptions()}
        <!-- Edit -->
        <GlyphButton
            style={[H2_BUTTON_ICON_STYLE(), "-padding0-lr"]}
            flowClass={FlowClass.ContextMenu}
            path={getGearPath(index)}

            tooltipEnabled={tooltipEnabled}
            tooltipDirection={TooltipDirection.UP}
            tooltipTheme={theme}
            tooltip={getLocalized("LA.edit.tooltip")}
            logText={getLocalized("LA.edit.tooltip")}
            logging={true}

            onPointerEnter={() => {editButtonHover = true;} }
            onPointerLeave={() => {editButtonHover = false;} }
        >
            <i class="fas fa-ellipsis-v"></i>
        </GlyphButton>
        <!-- Send to chat -->
        <GlyphButton
            style={[H2_BUTTON_ICON_STYLE(), "-padding0-lr"]}
            flowClass={FlowClass.SendToChat}
            index={index}
            uuid={gear.uuid}

            tooltipEnabled={tooltipEnabled}
            tooltipDirection={TooltipDirection.UP}
            tooltipTheme={theme}
            tooltip={getLocalized("LA.chat.tooltip")}
            logText={getLocalized("LA.chat.tooltip")}
            logging={true}

            onPointerEnter={() => {messageButtonHover = true;} }
            onPointerLeave={() => {messageButtonHover = false;} }
        >
            <i class="mdi mdi-message"></i>
        </GlyphButton>
    {/snippet}
        <HeaderSecondary
            text={gear.name}
            headerStyle={[H2_HEADER_STYLE, "la-bckg-pilot"]}
            textStyle={[H2_TEXT_SIZE, "-overflowhidden -fontface-stylized"]}
            borderStyle={["-bordersoff"]}
            extensionTextFunction={() => {
                if (messageButtonHover)
                    return `--${getLocalized("LA.chat.extension")}`;
                if (editButtonHover)
                    return `--${getLocalized("LA.edit.extension")}`;
                return undefined;
            }}

            itemID={gear.lid}
            uuid={gear.uuid}
            path={getGearPath(index)}
            acceptTypes={"pilot_gear"}
            
            collapseID={gear.uuid}
            startCollapsed={true}

            renderOutsideCollapse={renderOuter(gear) ? outerContent : undefined}
            contentLeft={headerSecondaryLeftOptions}
            contentRight={headerSecondaryRightOptions}
        >
            <div class="la-generated -widthfull -gap1 la-flexcol">
                <BonusBox
                    bonuses={gear.system.bonuses}
                    bonusPath={`${getGearPath(index)}.system.bonuses`}
                />
                <DeployableBox
                    source={actor}
                    lidSource={gear.system}
                    uuid={actor.uuid}
                    sheetUUID={actor.uuid}

                    tooltipEnabled={tooltipEnabled}
                    tooltipTheme={theme}
                    logging={true}
                />
                <ActionBox
                    actions={gear.system.actions}
                    actor={actor}
                    uuid={gear.uuid}
                    path={`system.actions`}

                    collapseID={`${gear.uuid}.actions`}
                    startCollapsed={true}

                    tooltipEnabled={tooltipEnabled}
                    tooltipTheme={theme}
                    logging={true}
                />
                <EffectBox
                    name={getLocalized("LA.description.label")}
                    effect={gear.system.description}

                    tooltipEnabled={tooltipEnabled}
                    logging={true}
                />
            {#if gear.system.effect}
                <EffectBox
                    name={getLocalized("LA.mech.system.effect.label")}
                    effect={gear.system.effect}

                    tooltipEnabled={tooltipEnabled}
                    logging={true}
                />
            {/if}
                <TagArray
                    tags={gear.system.tags}
                    justify={"start"}

                    tooltipEnabled={tooltipEnabled}
                    tooltipTheme={theme}
                />
            </div>
        </HeaderSecondary>
    {/each}
    </div>
{:else}
    <EmptyBox
        label={getLocalized("LA.pilot.gear.empty.label")}
        subLabel={getLocalized("LA.pilot.gear.empty.subLabel")}
        type={AcceptType.PilotGear}
        path="system.loadout.gear.{gears.length}.value"
    />
{/if}
</HeaderMain>