<!-- Wrapper handle for sorting -->
<script lang="ts">
    import { Logger } from "@/classes/Logger";
    import { TooltipFactory } from "@/classes/TooltipFactory";
    import { TooltipDirection } from "@/enums/TooltipDirection";
    import type { TextLogEventProps } from "@/interfaces/actor/TextLogEventProps";
    import type { TooltipProps } from "@/interfaces/actor/TooltipProps";
    import type { DragDropHandleProps } from "@/interfaces/dragdrop/DragDropHandleProps";
    import { getLocalized } from "@/scripts/helpers";
    import { resetTextConsole, sendToTextConsole } from "@/scripts/store/text-log";
    import { getActorContext } from "@/scripts/context";

    const {
        children,
        index,
        root,
        
        data,
        style,
        iconStyle,

        onDragStart,
        onDrop,
        onDropError,
        onDelete,

        disabled,
        deleteDisabled,

        tooltipDirection,
        tooltipClass,
        tooltipTheme,

        logging,
    }: DragDropHandleProps & TooltipProps & TextLogEventProps = $props();
    const actorUuid = getActorContext()?.uuid;
    let component: HTMLElement | null = $state(null);

    const deleteTip = TooltipFactory.buildTooltip(getLocalized("LA.delete.tooltip"));

    function handleDragStart(event: DragEvent): void 
    {
        try 
        {
            const jsonData = JSON.stringify(data);
            event.dataTransfer?.setData('text/plain', jsonData);
            onDragStart?.(event, data);
        } 
        catch (error) 
        {
            Logger.error('Failed to handle drag start', error);
        }
    }

    function handleDrop(event: DragEvent) 
    {
        event.preventDefault();
        const dropData = event.dataTransfer?.getData('text/plain');
        if (!dropData) return;

        try 
        {
            const obj = JSON.parse(dropData);
            if (obj.index !== index) 
            {
                const eventTarget = event.target as HTMLElement;
                // Do an additional check just in case this was being dropped
                // on a completely different root element that is listening for drops
                if (component && eventTarget && root &&
                    root.contains(component) && root.contains(eventTarget)) 
                {
                    onDrop?.(event, obj, data);
                }
                else 
                {
                    onDropError?.(event, obj);
                }
            }
        } 
        catch (error) 
        {
            Logger.error('Failed to parse drop data', error);
        }
    }

    function handleOnDelete(event: MouseEvent) 
    {
        event.stopPropagation();
        onDelete?.(event);
    }
</script>

<div role="none"
    class="la-flexrow -widthfull -aligncenter -positionrelative
        {style?.join(' ')}"
    ondragstart={handleDragStart}
    ondrop={handleDrop}
    draggable={!disabled}
    bind:this={component}
>
{#if !disabled}
    <i role="none"
        class="fas fa-grip-lines -positionabsolute -left0 -pointergrab la-prmy-primary -glow-prmy-hover {iconStyle?.join(' ')}"
        onpointerenter={ logging ? event => sendToTextConsole(event, getLocalized("LA.advanced.reorderMacro.tooltip"), actorUuid!) : undefined }
        onpointerleave={ logging ? event => resetTextConsole(event, actorUuid!) : undefined }
        style="z-index: 1;"
    ></i>
{/if}
{#if children}
    {@render children()}
{/if}
{#if !disabled && !deleteDisabled}
    <button type="button"
        class="mdi mdi-close-thick -positionabsolute -right0 la-prmy-error -glow-prmy-hover {iconStyle?.join(' ')}"
        onpointerenter={ logging ? event => sendToTextConsole(event, getLocalized("LA.delete.tooltip"), actorUuid!) : undefined }
        onpointerleave={ logging ? event => resetTextConsole(event, actorUuid!) : undefined }
        onclick={handleOnDelete}
        data-tooltip={deleteTip}
        data-tooltip-class={`${tooltipClass || "clipped-bot la-tooltip"} ${tooltipTheme}`}
        data-tooltip-direction={tooltipDirection || TooltipDirection.RIGHT}
        aria-label={getLocalized("LA.delete.tooltip")}
    ></button>
{/if}
</div>